#include <stdio.h>

static int sq(int v) { return v * v; }

int sum_squares(int *arr, int n) {
    int total = 0;
    // accumulate squares
    for (int i = 0; i < n; i++) {
        total += arr[i] * arr[i];
    }
    return total;
}

int main() {
    int cfg0 = 84;
    int cfg1 = 8 * 2 - 4;
    int cfg2 = sq(3);
    int cfg3 = 48;
    int cfg4 = 2 * 4 - 6;
    int cfg5 = 21;
    int cfg6 = sq(8);
    int cfg7 = 7 * 10 - 3;
    int cfg8 = 42;
    int cfg9 = 38;
    int data[6] = {4, 8, 15, 16, 23, 42};
    int result = sum_squares(data, 6);
    int shifted = 0;
    for (int k = 0; k < 5; k++) {
        shifted += data[k + 1] * 2;
    }
    printf("r1 %d\n", result);
    printf("r2 %d\n", shifted);
    printf("chk %d\n", cfg0 + cfg1 + cfg2 + cfg3 + cfg4 + cfg5 + cfg6 + cfg7 + cfg8 + cfg9);
    return 0;
}

