	// step 2
	long prev = 0;
	long curr = 1;  // done
	// step 4
	for (int step = 0; step < steps; step++) {
		long nxt = prev + curr;
		// step 6
		prev = curr;  // done
		curr = nxt;
	}
	// step 8
	return prev;
}

