static int sq(int v) { return v * v; }

long fib_iter(int n) {
    long a = 0;
    long b = 1;
    for (int i = 0; i < n; i++) {
        long next = a + b;
        a = b;
        b = next;
    }
    return a;
}

int main() {
    int cfg0 = 11;
    int cfg1 = 3 * 9 - 6;
    int cfg2 = sq(5);
    int cfg3 = 88;
    int cfg4 = 6 * 9 - 5;
    int cfg5 = 25;
    int cfg6 = sq(8);
    int cfg7 = 3 * 3 - 2;
    int cfg8 = 77;
    int cfg9 = 71;
    long f10 = fib_iter(10);
    long f20 = fib_iter(20);
    long total = 0;
    // sum of doubled values
    for (int n = 0; n < 8; n++) {
        total += fib_iter(n) * 2;
    }
    printf("r1 %ld\n", f10);
    printf("r2 %ld\n", f20);
    printf("r3 %ld\n", total);
    printf("chk %d\n", cfg0 + cfg1 + cfg2 + cfg3 + cfg4 + cfg5 + cfg6 + cfg7 + cfg8 + cfg9);
    return 0;
}

