#include <stdio.h>

static int sq(int v) { return v * v; }

long fibonacci_value(int steps) {
    long prev = 0;
    long curr = 1;
    {
        int step = 0;
        while (step < steps) {
            long nxt = prev + curr;
            prev = curr;
            curr = nxt;
            step++;
        }
    }
    return prev;
}

int main() {
    int option_a = 11;
    int option_b = 3 * 9 - 6;
    int option_e = 6 * 9 - 5;
    int option_f = 25;
    int option_g = sq(8);
    int option_c = sq(5);
    int option_d = 88;
    int option_h = 3 * 3 - 2;
    int option_i = 77;
    int option_j = 71;
    long ten = fibonacci_value(10);
    long twenty = fibonacci_value(20);
    long running = 0;
    // sum of doubled values
    {
        int steps = 0;
        while (steps < 8) {
            long tv0 = fibonacci_value(steps) * 2;
            running += tv0;
            steps++;
        }
    }
    printf("r1 %ld\n", ten);
    printf("r2 %ld\n", twenty);
    printf("r3 %ld\n", running);
    printf("chk %d\n", option_a + option_b + option_c + option_d + option_e + option_f + option_g + option_h + option_i + option_j);
    return 0;
}

