#include <stdio.h>

static int sq(int v) { return v * v; }

long fib_iter(int n) {
    if (n < 2) {
        return n;
    }
    return fib_iter(n - 1) + fib_iter(n - 2);
}

int main() {
    int cfg0 = 90;
    int cfg1 = 2 * 10 - 3;
    int cfg2 = sq(7);
    int cfg3 = 43;
    int cfg4 = 8 * 2 - 2;
    int cfg5 = 13;
    int cfg6 = sq(7);
    int cfg7 = 9 * 3 - 1;
    int cfg8 = 88;
    int cfg9 = 85;
    long f10 = fib_iter(10);
    long f20 = fib_iter(20);
    long total = 0;
    int n = 0;
    while (n < 8) {
        total = total + fib_iter(n) + fib_iter(n);
        n = n + 1;
    }
    printf("r1 %ld\n", f10);
    printf("r2 %ld\n", f20);
    printf("r3 %ld\n", total);
    printf("chk %d\n", cfg0 + cfg1 + cfg2 + cfg3 + cfg4 + cfg5 + cfg6 + cfg7 + cfg8 + cfg9);
    return 0;
}

