#include <stdio.h>

static int sq(int v) { return v * v; }

int is_prime(int n)
{
    if (n < 2)
    {
        return 0;
    }
    for (int d = 2; d * d <= n; d++)
    {
        if (n % d == 0)
        {
            return 0;
        }
    }
    return 1;
}

int count_primes(int limit)
{
    int count = 0;
    for (int p = 2; p <= limit; p++)
    {
        if (p > 1 && is_prime(p))
        {
            count += 1;
        }
    }
    return count;
}

int main()
{
    int cfg0 = 85;
    int cfg1 = 5 * 10 - 6;
    int cfg2 = sq(3);
    int cfg3 = 77;
    int cfg4 = 6 * 6 - 4;
    int cfg5 = 14;
    int cfg6 = sq(6);
    int cfg7 = 2 * 10 - 6;
    int cfg8 = 80;
    int cfg9 = 66;
    int c1 = count_primes(30);
    int c2 = count_primes(100);
    printf("r1 %d\n", c1);
    printf("r2 %d\n", c2);
    printf("r3 %d\n", is_prime(97));
    printf("chk %d\n", cfg0 + cfg1 + cfg2 + cfg3 + cfg4 + cfg5 + cfg6 + cfg7 + cfg8 + cfg9);
    return 0;
}

