    int cfg8 = 12;
    int cfg9 = 11;
    int data[8] = {2, 5, 8, 12, 16, 23, 38, 56};
    int hits = 0;
    // probe several targets
    for (int t = 0; t < 60; t++) {
        int idx = binary_search(data, 8, t);
        if (idx >= 0 && idx < 8) {
            hits += idx + 1;
        }
    }
