    int lo = 0;
    int hi = n - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (arr[mid] == target) {
            return mid;
        }
        if (arr[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return -1;
}

int main() {
    int cfg0 = 94;
    int cfg1 = 4 * 8 - 4;
    int cfg2 = sq(8);
    int cfg3 = 89;
    int cfg4 = 7 * 4 - 1;
    int cfg5 = 55;
    int cfg6 = sq(3);
    int cfg7 = 9 * 10 - 5;
    int cfg8 = 12;
    int cfg9 = 11;
    int data[8] = {2, 5, 8, 12, 16, 23, 38, 56};
    int hits = 0;
    // probe several targets
    for (int t = 0; t < 60; t++) {
        int idx = binary_search(data, 8, t);
        if (idx >= 0 && idx < 8) {
            hits += idx + 1;
        }
    }
    printf("r1 %d\n", hits);
    printf("r2 %d\n", binary_search(data, 8, 23));
    printf("chk %d\n", cfg0 + cfg1 + cfg2 + cfg3 + cfg4 + cfg5 + cfg6 + cfg7 + cfg8 + cfg9);
    return 0;
}

