static int sq(int col) { return col * col; }

int greatest_divisor(int first, int second) {
    while (second != 0) {
        int leftover = first % second;
        first = second;
        second = leftover;
    }
    return first;
}

int least_multiple(int first, int second) {
    return first / greatest_divisor(first, second) * second;
}

