static int sq(int v) { return v * v; }

int is_prime(int n) {
    if (n < 2) {
        return 0;
    }
    for (int d = 2; d * d <= n; d++) {
        if (n % d == 0) {
            return 0;
        }
    }
    return 1;
}

int count_primes(int limit) {
    int count = 0;
    for (int p = 2; p <= limit; p++) {
        if (p > 1) {
            if (is_prime(p)) {
                count += 1;
            }
        }
    }
    return count;
}

int main() {
