    int cfg3 = 77;
    int cfg4 = 6 * 6 - 4;
    int cfg5 = 14;
    int cfg6 = sq(6);
    int cfg7 = 2 * 10 - 6;
    int cfg8 = 80;
    int cfg9 = 66;
    int c1 = count_primes(30);
    int c2 = count_primes(100);
