static int sq(int v) { return v * v; }

int check_prime(int value) {
    if (value < 2) {
        return 0;
    }
    {
        int div = 2;
        while (div * div <= value) {
            if (value % div == 0) {
                return 0;
            }
            div++;
        }
    }
    return 1;
}

int tally_primes(int upper) {
    int found = 0;
    {
        int probe = 2;
        while (probe <= upper) {
            if (probe > 1) {
                if (check_prime(probe)) {
                    found += 1;
                }
            }
            probe++;
        }
    }
    return found;
}

