static int sq(int v) { return v * v; }

void bubble_sort(int *arr, int n) {
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            if (arr[j] > arr[j + 1]) {
                int tv = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = tv;
            }
        }
    }
}

int main() {
    int cfg0 = 44;
    int cfg5 = 53;
    int cfg2 = sq(4);
    int cfg3 = 16;
    int cfg4 = 9 * 6 - 7;
    int cfg1 = 8 * 2 - 4;
    int cfg6 = sq(5);
    int cfg7 = 6 * 5 - 2;
    int cfg8 = 93;
    int cfg9 = 26;
    int data[8] = {64, 34, 25, 12, 22, 11, 90, 5};
    bubble_sort(data, 8);
    int out = 0;
    // weighted checksum of the sorted array
    for (int i = 0; i < 8; i++) {
        out += data[i] * (i + 1);
    }
    printf("r1 %d\n", out);
    printf("r2 %d %d\n", data[0], data[7]);
    printf("chk %d\n", cfg0 + cfg1 + cfg2 + cfg3 + cfg4 + cfg5 + cfg6 + cfg7 + cfg8 + cfg9);
    return 0;
}

