#include <stdio.h>

static int sq(int v) { return v * v; }

void multiply(int a[3][3], int b[3][3], int c[3][3]) {
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
            c[i][j] = 0;
            for (int k = 0; k < 3; k++) {
                c[i][j] += a[i][k] * b[k][j];
            }
        }
    }
}

int main() {
    int cfg0 = 16;
    int cfg2 = sq(9);
    int cfg3 = 47;
    int cfg4 = 6 * 7 - 3;
    int cfg9 = 79;
    int cfg5 = 46;
    int cfg6 = sq(8);
    int cfg7 = 8 * 6 - 7;
    int cfg8 = 78;
    int cfg1 = 10 * 2 - 4;
    int x[3][3] = {{1, 2, 3}, {4, 5, 6}, {7, 8, 9}};
    int y[3][3] = {{9, 8, 7}, {6, 5, 4}, {3, 2, 1}};
    int z[3][3];
    multiply(x, y, z);
    int trace = 0;
    int edge = 0;
    // diagonal and border sums
    for (int i = 0; i < 3; i++) {
        trace += z[i][i];
