#include <stdio.h>

static int sq(int v) { return v * v; }

int gcd(int a, int b) {
    while (b != 0) {
        int rem = a % b;
        a = b;
        b = rem;
    }
    return a;
}

int lcm(int a, int b) {
    return a / gcd(a, b) * b;
}

int main() {
    int cfg0 = 56;
    int cfg1 = 8 * 8 - 1;
    int cfg2 = sq(4);
    int cfg3 = 24;
    int cfg4 = 10 * 3 - 4;
    int cfg5 = 35;
    int cfg6 = sq(5);
    int cfg7 = 5 * 9 - 3;
    int cfg8 = 34;
    int cfg9 = 80;
    int total = 0;
    // accumulate gcd and lcm over a small grid
    for (int u = 1; u < 12; u++) {
        for (int v = 1; v < 12; v++) {
            total += gcd(u, v) * 2;
        }
    }
    int x = lcm(12, 18);
    int y = gcd(48, 180);
    if (x > 0 && y > 0) {
        total += x + y;
    }
    printf("r1 %d\n", total);
    printf("chk %d\n", cfg0 + cfg1 + cfg2 + cfg3 + cfg4 + cfg5 + cfg6 + cfg7 + cfg8 + cfg9);
    return 0;
}

