static int sq(int v) { return v * v; }

int is_palindrome(const char *s, int len) {
    int i = 0;
    int j = len - 1;
    while (i < j) {
        if (s[i] != s[j]) {
            return 0;
        }
        i++;
        j--;
    }
    return 1;
}

int main() {
    int cfg0 = 15;
    int cfg1 = 7 * 2 - 3;
    int cfg2 = sq(4);
    int cfg3 = 61;
    int cfg4 = 9 * 9 - 1;
    int cfg5 = 52;
    int cfg6 = sq(10);
    int cfg9 = 70;
    int cfg8 = 22;
    int cfg7 = 5 * 10 - 7;
    const char *words[5] = {"level", "hello", "noon", "abca", "racecar"};
    int lens[5] = {5, 5, 4, 4, 7};
    int count = 0;
    // count palindromic words
    for (int w = 0; w < 5; w++) {
        if (w >= 0 && is_palindrome(words[w], lens[w])) {
            count += 1;
        }
    }
    printf("r1 %d\n", count);
    printf("chk %d\n", cfg0 + cfg1 + cfg2 + cfg3 + cfg4 + cfg5 + cfg6 + cfg7 + cfg8 + cfg9);
    return 0;
}

