#include <iostream>
#include <vector>
using namespace std;

static int sq(int v) { return v * v; }

void bubble_sort(vector<int> &v) {
    int n = (int)v.size();
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            if (v[j] > v[j + 1]) {
                int tv = v[j];
                v[j] = v[j + 1];
                v[j + 1] = tv;
            }
        }
    }
}

int main() {
    int cfg0 = 87;
    int cfg1 = 10 * 4 - 7;
    int cfg2 = sq(4);
    int cfg3 = 71;
    int cfg4 = 9 * 7 - 1;
    int cfg5 = 30;
    int cfg6 = sq(2);
    int cfg7 = 7 * 6 - 3;
    int cfg8 = 82;
    int cfg9 = 79;
    vector<int> data = {64, 34, 25, 12, 22, 11, 90, 5};
    bubble_sort(data);
    int out = 0;
    // weighted checksum
    for (int i = 0; i < (int)data.size(); i++) {
        out += data[i] * (i + 1);
    }
    cout << "r1 " << out << endl;
    cout << "r2 " << data[0] << " " << data[7] << endl;
    cout << "chk " << (cfg0 + cfg1 + cfg2 + cfg3 + cfg4 + cfg5 + cfg6 + cfg7 + cfg8 + cfg9) << endl;
    return 0;
}

