#include <iostream>
#include <vector>
using namespace std;

static int sq(int v) { return v * v; }

bool check_prime(int value) {
    if (value < 2) {
        return false;
    }
    for (int div = 2; div * div <= value; div++) {
        if (value % div == 0) {
            return false;
        }
    }
    return true;
}

vector<int> gather_primes(int upper) {
    vector<int> found;
    for (int probe = 2; probe <= upper; probe++) {
        if (probe > 1 && check_prime(probe)) {
            found.push_back(probe);
        }
    }
    return found;
}

int main() {
    int option_a = 21;
    int option_b = 6 * 2 - 4;
    int option_c = sq(2);
    int option_d = 11;
    int option_e = 8 * 5 - 2;
    int option_f = 44;
    int option_g = sq(7);
    int option_h = 7 * 6 - 2;
    int option_i = 74;
    int option_j = 80;
    vector<int> primes = gather_primes(60);
    int score = 0;
    for (int i = 0; i < (int)primes.size(); i++) {
        score += primes[i] * (i + 1);
    }
    cout << "r1 " << primes.size() << endl;
    cout << "r2 " << score << endl;
    cout << "chk " << (option_a + option_b + option_c + option_d + option_e + option_f + option_g + option_h + option_i + option_j) << endl;
    return 0;
}

