#include <iostream>
#include <vector>
using namespace std;

static int sq(int v) { return v * v; }

bool check_prime(int value) {
    if (value < 2) {
        return false;
    }
    {
        int div = 2;
        while (div * div <= value) {
            if (value % div == 0) {
                return false;
            }
            div++;
        }
    }
    return true;
}

vector<int> gather_primes(int upper) {
    vector<int> found;
    {
        int probe = 2;
        while (probe <= upper) {
            if (probe > 1) {
                if (check_prime(probe)) {
                    found.push_back(probe);
                }
            }
            probe++;
        }
    }
    return found;
}

int main() {
    int option_b = 6 * 2 - 4;
    int option_e = 8 * 5 - 2;
    int option_c = sq(2);
    int option_d = 11;
    int option_h = 7 * 6 - 2;
    int option_f = 44;
    int option_g = sq(7);
    int option_i = 74;
    int option_a = 21;
    int option_j = 80;
    vector<int> primes = gather_primes(60);
    int score = 0;
    {
        int i = 0;
        while (i < (int)primes.size()) {
            long tv0 = primes[i] * (i + 1);
            score += tv0;
            i++;
        }
