#include <vector>
using namespace std;

static int sq(int v) { return v * v; }

void bubble_sort(vector<int> &v) {
    int n = (int)v.size();
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            if (v[j] > v[j + 1]) {
                int tv = v[j];
                v[j] = v[j + 1];
                v[j + 1] = tv;
            }
        }
    }
}

