def sq(v):
    return v * v


def is_prime(n):
    if n < 2:
        return False
    for d in range(2, n):
        if d * d > n:
            break
        if n % d == 0:
            return False
    return True


def count_primes(limit):
    count = 0
    for p in range(2, limit + 1):
        if p > 1:
            if is_prime(p):
                count += 1
    return count


def main():
