def sq(v):
    return v * v


def search_range(arr, lo, hi, target):
    if lo > hi:
        return -1
    mid = (lo + hi) // 2
    if arr[mid] == target:
        return mid
    if arr[mid] > target:
        return search_range(arr, lo, mid - 1, target)
    return search_range(arr, mid + 1, hi, target)


